@import 'c/rlySharedStyles';

:host {
    padding-bottom: 1.5rem;
    display: block;
    height: 100%;
    --rr-blue: #0176d3;
    --rr-blue-2: #eef4ff;
    --rr-link: #0b5cab;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
    --rr-head-bg: #fafaf9;
    --rr-ok: #2e844a;
    --rr-ok-2: #ebf7e6;
    --rr-bad: #ba0517;
    --rr-bad-2: #feded8;
    --rr-warn: #8c4b02;
    --rr-warn-2: #fef1cd;
    --rr-violet: #5a1ba9;
    --rr-violet-2: #f2eafe;
    --rr-mono: ui-monospace, Menlo, Consolas, monospace;
}

.rr-page p { margin: 0; }
.rr-card { background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); min-width: 0; }
.rr-grow { flex: 1 1 auto; }
.rr-strong { font-weight: 600; }
.rr-mono { font-family: var(--rr-mono); font-size: 12px; white-space: nowrap; }
.rr-pad { padding: 6px 12px; }
.rr-inset { margin: 10px 12px; }
.rr-bad-text { color: #8e030f; }
.rr-hit { background: #fff3b0; border-radius: 2px; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; flex: none; }
.rr-a { color: var(--rr-link); text-decoration: none; white-space: nowrap; }
.rr-a:hover, .rr-link:hover { text-decoration: underline; }
.rr-link { border: 0; background: none; padding: 0; font: inherit; color: var(--rr-link); cursor: pointer; text-align: left; }

.rr-segs { display: inline-flex; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; flex-wrap: wrap; }
.rr-seg { border: 0; border-right: 1px solid #c9c9c9; background: #fff; padding: 5px 12px; font: inherit; font-size: 12px; cursor: pointer; color: var(--rr-ink); }
.rr-seg:last-child { border-right: 0; }
.rr-seg-on { background: var(--rr-blue); color: #fff; }

.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-ok { background: var(--rr-ok-2); color: var(--rr-ok); }
.rr-pill-bad { background: var(--rr-bad-2); color: var(--rr-bad); }
.rr-pill-none { background: #f3f3f3; color: var(--rr-muted); }
.rr-pill-violet { background: var(--rr-violet-2); color: var(--rr-violet); }

.rr-tick { position: absolute; width: 1px; height: 1px; opacity: 0.01; pointer-events: none; animation: rr-tick 1s linear; }
@keyframes rr-tick { from { transform: translateX(0); } to { transform: translateX(1px); } }

.rr-data { display: grid; grid-template-columns: minmax(220px, 300px) 1fr; gap: 12px; height: 100%; min-height: 0; position: relative; }
.rr-col { display: flex; flex-direction: column; min-height: 0; }
.rr-scroll { overflow: auto; min-height: 0; flex: 1 1 auto; }
.rr-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--rr-line); }
.rr-set { display: block; width: 100%; text-align: left; border: 0; border-bottom: 1px solid #f1f1f1; background: #fff; padding: 9px 12px; cursor: pointer; font: inherit; color: var(--rr-ink); }
.rr-set-on { background: #f4f8fe; box-shadow: inset 3px 0 0 var(--rr-blue); }
.rr-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.rr-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: var(--rr-muted); background: var(--rr-head-bg); padding: 6px 10px; border-bottom: 1px solid var(--rr-line); position: sticky; top: 0; }
.rr-table td { padding: 6px 10px; border-bottom: 1px solid #f1f1f1; vertical-align: top; }
.rr-form { display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; padding: 10px 12px; border-bottom: 1px solid var(--rr-line); }
.rr-form lightning-combobox, .rr-form lightning-input { min-width: 160px; }
.rr-note { margin: 8px 12px; padding: 8px 10px; border-radius: 4px; background: var(--rr-warn-2); color: #5c3a00; font-size: 12px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rr-detail { background: #fafcff; }
.rr-chip { border: 1px solid #c9c9c9; border-radius: 14px; padding: 3px 10px; font: inherit; font-size: 12px; font-weight: 600; color: var(--rr-blue); background: #fff; cursor: pointer; }
.rr-chip-on { background: var(--rr-blue); border-color: var(--rr-blue); color: #fff; }
.rr-modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.35); z-index: 9000; display: flex; align-items: flex-start; justify-content: center; padding: 40px 16px; overflow: auto; }
.rr-dialog { background: #fff; border-radius: 6px; width: min(1100px, 100%); box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2); padding-bottom: 12px; }
.rr-dialog-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-bottom: 1px solid var(--rr-line); }
.rr-obj { border: 1px solid var(--rr-line); border-radius: 4px; margin: 10px 14px; padding: 8px 10px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.rr-obj-head { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; }
.rr-foot { display: flex; align-items: center; gap: 8px; padding: 10px 14px 0; flex-wrap: wrap; }
@media (max-width: 900px) { .rr-data { grid-template-columns: 1fr; } .rr-obj { grid-template-columns: 1fr; } }
